+// Quote-aware parser for the legacy CSV import format.
+// Replaces src/legacy/csvImport.ts for POST /import (that file must not be edited and
+// splits on every comma, so quoted values like "Müller, Hans" broke the columns).
+// Expected header: tracking,carrier,service,name,street,zip,city,country,phone
+import { mapLegacyCarrier } from '../legacy/carrierCodes.ts';
+import type { LegacyRow } from '../legacy/csvImport.ts';
+
+/** RFC 4180-style tokenizer: quoted fields may contain commas, newlines and "" escapes. */
+export function parseCsvRecords(text: string): string[][] {
+  const records: string[][] = [];
+  let record: string[] = [];
+  let field = '';
+  let inQuotes = false;
+
+  const endField = (): void => {
+    record.push(field);
+    field = '';
+  };
+  const endRecord = (): void => {
+    endField();
+    if (record.some((c) => c.trim() !== '')) records.push(record);
+    record = [];
+  };
+
+  for (let i = 0; i < text.length; i++) {
+    const ch = text[i];
+    if (inQuotes) {
+      if (ch === '"') {
+        if (text[i + 1] === '"') {
+          field += '"';
+          i++;
+        } else {
+          inQuotes = false;
+        }
+      } else {
+        field += ch;
+      }
+    } else if (ch === '"') {
+      inQuotes = true;
+    } else if (ch === ',') {
+      endField();
+    } else if (ch === '\n' || ch === '\r') {
+      if (ch === '\r' && text[i + 1] === '\n') i++;
+      endRecord();
+    } else {
+      field += ch;
+    }
+  }
+  endRecord();
+  return records;
+}
+
+export function parseImportCsv(text: string): LegacyRow[] {
+  const records = parseCsvRecords(text.replace(/^﻿/, ''));
+  if (records.length === 0) return [];
+
+  const header = records[0].map((h) => h.trim().toLowerCase());
+  return records.slice(1).map((cells) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
+    const phone = get('phone');
+    return {
+      tracking_number: get('tracking'),
+      carrier: mapLegacyCarrier(get('carrier')),
+      service_level: get('service') || 'standard',
+      recipient: {
+        name: get('name'),
+        street: get('street'),
+        zip: get('zip'),
+        city: get('city'),
+        country: get('country') || 'AT',
+        ...(phone ? { phone } : {}),
+      },
+    };
+  });
+}
